.concept-5{--p5-ink:#f7f4ec;--p5-muted:#d8ddd9;--p5-dark:#10201b;--p5-green:#25483b;--p5-gold:#e7c79d;--p5-line:rgba(255,255,255,.32);background:#f4f6f3;color:#20312c;min-width:0}.concept-5 *{box-sizing:border-box}.concept-5 button{font:inherit;cursor:pointer}.concept-5 .p5-wrap{width:min(1180px,calc(100% - 64px));margin-inline:auto}.concept-5 .p5-hero{position:relative;min-height:650px;overflow:hidden;isolation:isolate;background:#17231f}.concept-5 .p5-photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center center;z-index:-3;transition:transform .7s cubic-bezier(.16,1,.3,1),filter .7s ease}.concept-5 .p5-hero::before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(90deg,rgba(9,16,14,.88) 0%,rgba(9,16,14,.68) 37%,rgba(9,16,14,.24) 67%,rgba(9,16,14,.12) 100%),linear-gradient(0deg,rgba(8,15,13,.58),transparent 52%)}.concept-5 .p5-hero::after{content:'';position:absolute;inset:0;z-index:-1;background:radial-gradient(circle at 77% 57%,rgba(110,153,185,.14),transparent 32%);pointer-events:none;transition:opacity .4s ease}.concept-5 .p5-head{min-height:82px;display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--p5-line);color:#fff}.concept-5 .p5-brand{display:flex;align-items:center;gap:11px;color:#fff;text-decoration:none;font-size:19px;font-weight:730;letter-spacing:-.03em;white-space:nowrap}.concept-5 .p5-brand-mark{width:12px;height:12px;border:2px solid var(--p5-gold);transform:rotate(45deg);flex:none}.concept-5 .p5-nav{display:flex;align-items:center;gap:4px}.concept-5 .p5-nav button{min-height:44px;padding:8px 13px;border:0;background:transparent;color:#f8faf8;font-size:13px;font-weight:650;border-radius:4px}.concept-5 .p5-nav button:hover{background:rgba(255,255,255,.1)}.concept-5 .p5-nav button:last-child{margin-left:5px;padding-inline:17px;border:1px solid rgba(255,255,255,.76);background:rgba(7,18,14,.42)}.concept-5 .p5-nav button:last-child:hover{background:#fff;color:#183128}.concept-5 .p5-hero-grid{min-height:568px;display:grid;grid-template-columns:minmax(0,1fr) 352px;gap:clamp(40px,7vw,96px);align-items:center;padding-block:54px 61px}.concept-5 .p5-copy{max-width:680px;color:var(--p5-ink)}.concept-5 .p5-label{display:flex;align-items:center;gap:10px;margin:0 0 22px;color:var(--p5-gold);font-size:13px;font-weight:680}.concept-5 .p5-label::before{content:'';width:28px;height:1px;background:currentColor}.concept-5 h1{margin:0;font-size:clamp(48px,5.3vw,76px);line-height:1.12;letter-spacing:-.036em;font-weight:620;text-wrap:balance}.concept-5 .p5-verb{display:block;color:#f3d3aa;font-weight:760}.concept-5 .p5-description{max-width:34em;min-height:56px;margin:22px 0 0;color:#e2e7e3;font-size:15px;line-height:1.8;text-wrap:pretty}.concept-5 .p5-copy.is-changing .p5-verb,.concept-5 .p5-copy.is-changing .p5-description{animation:p5-settle .36s both cubic-bezier(.16,1,.3,1)}.concept-5 .p5-proposal{align-self:stretch;display:flex;flex-direction:column;justify-content:center;color:#fff}.concept-5 .p5-proposal-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:15px}.concept-5 .p5-proposal-head strong{font-size:14px;letter-spacing:-.01em}.concept-5 .p5-proposal-head span{color:#cbd2ce;font-size:11px}.concept-5 .p5-directions{display:flex;flex-direction:column;border-top:1px solid var(--p5-line)}.concept-5 .p5-index-item{position:relative;display:grid;grid-template-columns:35px 1fr auto;gap:12px;align-items:center;min-height:88px;padding:14px 0;border:0;border-bottom:1px solid var(--p5-line);background:transparent;color:#fff;text-align:left;transition:padding .24s cubic-bezier(.16,1,.3,1),background .2s ease}.concept-5 .p5-index-item::before{content:'';position:absolute;inset:0 -16px;background:rgba(255,255,255,.1);opacity:0;transform:scaleX(.96);transition:opacity .2s ease,transform .24s cubic-bezier(.16,1,.3,1);z-index:-1}.concept-5 .p5-index-item:hover::before,.concept-5 .p5-index-item[aria-pressed=true]::before{opacity:1;transform:scaleX(1)}.concept-5 .p5-index-item[aria-pressed=true]{padding-left:8px}.concept-5 .p5-number{color:var(--p5-gold);font-size:12px;font-weight:720}.concept-5 .p5-index-copy{display:flex;flex-direction:column;gap:4px}.concept-5 .p5-index-copy strong{font-size:16px;letter-spacing:-.02em}.concept-5 .p5-index-copy small{color:#cbd3cf;font-size:11px;line-height:1.4}.concept-5 .p5-index-state{width:8px;height:8px;border:1px solid rgba(255,255,255,.7);border-radius:50%;transition:background .18s ease,box-shadow .18s ease}.concept-5 .p5-index-item[aria-pressed=true] .p5-index-state{background:var(--p5-gold);border-color:var(--p5-gold);box-shadow:0 0 0 4px rgba(231,199,157,.18)}.concept-5 .p5-proposal-note{margin:16px 0 0;color:#cbd3cf;font-size:11px;line-height:1.6}.concept-5 .p5-hero[data-scene=facility] .p5-photo{transform:scale(1.035) translateX(-8px);filter:saturate(.9)}.concept-5 .p5-hero[data-scene=support] .p5-photo{transform:scale(1.02) translateY(-7px);filter:saturate(1.06)}.concept-5 .p5-hero[data-scene=support]::after{opacity:.52}.concept-5 .p5-sr{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.concept-5 .p5-prep{background:#eef2ee;padding:28px 0}.concept-5 .p5-prep-inner{display:grid;grid-template-columns:minmax(300px,.86fr) 1.14fr;min-height:224px;background:#fff}.concept-5 .p5-prep-visual{position:relative;overflow:hidden;min-height:224px}.concept-5 .p5-prep-visual img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 58%}.concept-5 .p5-prep-visual::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent 70%,rgba(255,255,255,.2))}.concept-5 .p5-prep-copy{display:grid;grid-template-columns:1fr auto;gap:22px;align-items:center;padding:29px clamp(24px,4vw,50px)}.concept-5 .p5-prep-copy h2{margin:0 0 8px;font-size:26px;line-height:1.25;letter-spacing:-.03em;font-weight:720}.concept-5 .p5-prep-copy p{margin:0;color:#5a6a62;font-size:13px;line-height:1.7}.concept-5 .p5-checks{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0 0;padding:0;list-style:none}.concept-5 .p5-checks li{display:flex;align-items:center;gap:6px;color:#33483e;font-size:12px;font-weight:650}.concept-5 .p5-checks li::before{content:'';width:6px;height:6px;border-radius:50%;background:#b88956}.concept-5 .p5-prep .primary{min-height:50px;padding:10px 23px;border-radius:4px;background:var(--p5-green);border-color:var(--p5-green);white-space:nowrap}.concept-5 .p5-footer{border-top:1px solid #d8dfda;background:#f7f8f6;padding:21px 0}.concept-5 .p5-footer .p5-wrap{display:grid;grid-template-columns:1fr 1.15fr;gap:36px;color:#596a61;font-size:11px;line-height:1.7}.concept-5 .p5-footer p{margin:0}.concept-5 .p5-footer .restriction{color:#344a3f;font-size:12px}.concept-5 :is(button,a):focus-visible{outline:3px solid #f3d3aa;outline-offset:4px}.concept-5 .p5-prep :is(button,a):focus-visible{outline-color:#315f4e}@keyframes p5-settle{from{opacity:.45;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:900px){.concept-5 .p5-wrap{width:calc(100% - 44px)}.concept-5 .p5-head{align-items:flex-start;flex-direction:column;gap:6px;padding-block:12px}.concept-5 .p5-nav{width:100%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:3px}.concept-5 .p5-nav button,.concept-5 .p5-nav button:last-child{display:flex;align-items:center;justify-content:center;min-width:0;min-height:44px;margin-left:0;padding:7px 3px;font-size:11px;line-height:1.2;white-space:nowrap}.concept-5 .p5-hero-grid{min-height:578px;grid-template-columns:minmax(0,1fr) 290px;gap:34px;padding-block:42px 48px}.concept-5 h1{font-size:clamp(44px,7vw,62px)}.concept-5 .p5-prep-copy{grid-template-columns:1fr}.concept-5 .p5-prep .primary{justify-self:start}}
@media(max-width:700px){.concept-5 .p5-wrap{width:calc(100% - 36px)}.concept-5 .p5-hero{min-height:700px}.concept-5 .p5-photo{object-position:64% center}.concept-5 .p5-hero::before{background:linear-gradient(90deg,rgba(9,16,14,.89),rgba(9,16,14,.42)),linear-gradient(0deg,rgba(8,15,13,.72),transparent 55%)}.concept-5 .p5-head{min-height:116px}.concept-5 .p5-brand{font-size:17px}.concept-5 .p5-hero-grid{min-height:584px;display:block;padding-block:38px 34px}.concept-5 .p5-copy{max-width:none}.concept-5 .p5-label{margin-bottom:15px;font-size:12px}.concept-5 h1{font-size:clamp(39px,11.2vw,50px);line-height:1.14;letter-spacing:-.032em}.concept-5 .p5-description{min-height:72px;margin-top:17px;font-size:13px;line-height:1.68}.concept-5 .p5-proposal{margin-top:28px}.concept-5 .p5-proposal-head{margin-bottom:8px}.concept-5 .p5-index-item{grid-template-columns:28px 1fr auto;min-height:62px;padding-block:9px;gap:8px}.concept-5 .p5-index-item[aria-pressed=true]{padding-left:5px}.concept-5 .p5-index-item::before{inset:0 -8px}.concept-5 .p5-index-copy strong{font-size:14px}.concept-5 .p5-index-copy small{font-size:10px}.concept-5 .p5-proposal-note{display:none}.concept-5 .p5-prep{padding:18px 0}.concept-5 .p5-prep-inner{display:grid;grid-template-columns:1fr;min-height:0}.concept-5 .p5-prep-visual{min-height:145px}.concept-5 .p5-prep-visual img{object-position:center 62%}.concept-5 .p5-prep-copy{display:block;padding:23px 20px 24px}.concept-5 .p5-prep-copy h2{font-size:22px}.concept-5 .p5-prep-copy p{font-size:12px}.concept-5 .p5-checks{gap:5px 12px;margin-top:12px}.concept-5 .p5-checks li{font-size:11px}.concept-5 .p5-prep .primary{width:100%;margin-top:18px;min-height:48px}.concept-5 .p5-footer{padding:18px 0}.concept-5 .p5-footer .p5-wrap{grid-template-columns:1fr;gap:10px}.concept-5 .p5-footer .restriction{font-size:11px}}
@media(max-width:370px){.concept-5 .p5-wrap{width:calc(100% - 28px)}.concept-5 .p5-nav button,.concept-5 .p5-nav button:last-child{font-size:10px}.concept-5 h1{font-size:38px}.concept-5 .p5-index-copy small{display:none}}
@media(prefers-reduced-motion:reduce){.concept-5 *,.concept-5 *::before,.concept-5 *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

@media(max-width:700px){.concept-5 .p5-hero{min-height:628px}.concept-5 .p5-hero-grid{min-height:512px;padding-block:30px 24px}.concept-5 .p5-proposal{margin-top:22px}.concept-5 .p5-index-item{min-height:58px}.concept-5 .p5-prep{padding:14px 0}.concept-5 .p5-prep-visual{min-height:128px}.concept-5 .p5-prep-copy{padding:18px 20px}.concept-5 .p5-prep .primary{margin-top:14px}.concept-5 .p5-footer{padding:14px 0}.concept-5 .p5-footer .p5-wrap{gap:7px}}
